"""Generate the Dart contract from the shared Desktop catalog, without packages."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
schema = json.loads((root / 'docs/hermes-openui/references/catalog.schema.json').read_text())
(root / 'lib/features/hermes/services/hermes_openui_schema.dart').write_text(
    '// Generated by tool/generate_hermes_openui_schema.py. Do not edit.\n'
    'const hermesOpenuiSchemaJson = r"""' + json.dumps(schema['$defs'], separators=(',', ':')) + '""";\n'
)
